import {foodCarousel,mountEngagement} from './restaurant-engagement';


import {createElement} from 'react';
import {renderToStaticMarkup} from 'react-dom/server.browser';
import {MapPin,Heart,CalendarDays,Flame,House,Utensils,ShoppingBag,UserRound,ChevronLeft,ChevronRight,Search,Check,ArrowRight,ArrowUpRight,Store,Wallet,CreditCard,Receipt,BriefcaseBusiness,Bell,CircleHelp,MessagesSquare,Minus,Plus,LoaderCircle,RefreshCw,ClipboardList,Mail} from 'lucide-react';
const iconMap={'map-pin':MapPin,heart:Heart,'calendar-days':CalendarDays,flame:Flame,house:House,utensils:Utensils,'shopping-bag':ShoppingBag,'user-round':UserRound,'chevron-left':ChevronLeft,'chevron-right':ChevronRight,search:Search,check:Check,'arrow-right':ArrowRight,'arrow-up-right':ArrowUpRight,store:Store,wallet:Wallet,'credit-card':CreditCard,receipt:Receipt,'briefcase-business':BriefcaseBusiness,bell:Bell,'circle-help':CircleHelp,'messages-square':MessagesSquare,minus:Minus,plus:Plus,'loader-circle':LoaderCircle,'refresh-cw':RefreshCw,'clipboard-list':ClipboardList,mail:Mail};
export function mountIle(){
let currentDate=new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Lagos',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const controller=new AbortController(),listen=(type,handler)=>root.addEventListener(type,handler,{signal:controller.signal});

const root=document.getElementById('ile-preview'),app=root.querySelector('.app'),message=root.querySelector('.message');
let engagement;
const assets={"jollof":"/photos/jollof.jpg","rice":"/photos/rice.jpg","egusi":"/photos/egusi.jpg","suya":"/photos/suya.jpg","zobo":"/photos/zobo.jpg","ofada":"/photos/ofada.jpg","efo":"/photos/efo.jpg","peppersoup":"/photos/peppersoup.jpg","croaker":"/photos/croaker.jpg","moimoi":"/photos/moimoi.jpg","chapman":"/photos/chapman.jpg","feast":"/photos/jollof.jpg","plantain":"/photos/plantain.jpg"};
const I=n=>`<i class="ic" data-lucide="${n}" aria-hidden="true"></i>`;
const money=n=>'₦'+n.toLocaleString('en-NG');
const meals=[{"id":"jollof","name":"Smoky jollof & chicken","short":"Smoky jollof","sub":"With grilled chicken skewers","price":8500,"cat":"Rice","img":"jollof","description":"Our tomato-rich party jollof, slowly cooked for that smoky finish. Served with pepper-marinated grilled chicken skewers.","allergens":"Ask our team about ingredient and allergy requirements."},{"id":"rice","name":"Party jollof rice","short":"Party jollof rice","sub":"Tomatoes, peppers & warm spices","price":4500,"cat":"Rice","description":"Long-grain rice cooked in a rich tomato and pepper base. Deep flavour, a smoky finish, and all the comfort of a Nigerian party.","allergens":"Ask our team about ingredient and allergy requirements.","img":"rice"},{"id":"egusi","name":"Egusi & pounded yam","short":"Egusi & pounded yam","sub":"Melon-seed soup · assorted meat","price":9500,"cat":"Soups","description":"Rich egusi soup with leafy greens and assorted meat, served with freshly made pounded yam.","allergens":"Contains fish and shellfish in this sample recipe.","img":"egusi"},{"id":"suya","name":"Beef suya","short":"Beef suya","sub":"Yaji spice · onions · tomatoes","price":6500,"cat":"Grills","description":"Thinly sliced beef, rubbed with yaji and grilled over an open flame. Served with fresh onions and tomatoes.","allergens":"Contains groundnuts.","img":"suya"},{"id":"zobo","name":"House zobo","short":"House zobo","sub":"Hibiscus · ginger · pineapple","price":2000,"cat":"Drinks","description":"A chilled hibiscus infusion with ginger and pineapple. Bright, refreshing and made in-house.","allergens":"Ask our team about ingredient and allergy requirements.","img":"zobo"},{"id":"ofada","name":"Ofada rice & ayamase","short":"Ofada & ayamase","sub":"Local rice · green-pepper sauce","price":10500,"cat":"Rice","description":"Fragrant local ofada rice with rich green-pepper ayamase, assorted meat and a boiled egg.","allergens":"Contains egg. Ask about ingredient requirements.","img":"ofada"},{"id":"efo","name":"Efo riro & amala","short":"Efo riro & amala","sub":"Leafy greens · pepper · assorted meat","price":9000,"cat":"Soups","description":"Leafy efo riro in a rich pepper base, with assorted meat and soft amala on the side.","allergens":"Contains fish and shellfish in this sample recipe.","img":"efo"},{"id":"peppersoup","name":"Goat meat pepper soup","short":"Goat meat pepper soup","sub":"Aromatic broth · Nigerian spices","price":7500,"cat":"Soups","description":"Tender goat meat in a warming broth of Nigerian pepper-soup spices. Comforting, fragrant and full of flavour.","allergens":"Ask our team about ingredient and allergy requirements.","img":"peppersoup"},{"id":"croaker","name":"Grilled croaker","short":"Grilled croaker","sub":"Whole fish · pepper sauce · plantain","price":18000,"cat":"Grills","description":"A whole croaker, marinated with peppers and spices, then grilled. Served with pepper sauce and fried plantain.","allergens":"Contains fish.","img":"croaker"},{"id":"moimoi","name":"Moi moi","short":"Moi moi","sub":"Steamed bean pudding","price":2500,"cat":"Sides","description":"Soft steamed bean pudding, seasoned with peppers and onions. A familiar companion to your favourite rice.","allergens":"Contains fish and egg in this sample recipe.","img":"moimoi"},{"id":"chapman","name":"House Chapman","short":"House Chapman","sub":"Citrus · cucumber · grenadine","price":3500,"cat":"Drinks","description":"Our refreshing alcohol-free Chapman with citrus, cucumber and a splash of grenadine. Served chilled.","allergens":"Ask our team about ingredient and allergy requirements.","img":"chapman"}];
let view='Welcome',category='All',query='',selected=meals[0],quantity=1,heat='Medium',extra=false,bag=[],fulfil='Pickup',slot='7:00 PM',booking=null,saved=new Set(),draft={date:currentDate,guests:'2 guests',name:'',phone:'',seating:'Dining room',occasion:'Just dinner'},orderName='',address='';

const totalQty=()=>bag.reduce((a,b)=>a+b.qty,0),subtotal=()=>bag.reduce((a,b)=>a+b.unit*b.qty,0);
function note(t){message.textContent=t}
function nav(dark=false){return `<nav class="nav ${dark?'menu-nav':''}" aria-label="App navigation"><button class="navbrand cursor-interaction" data-view="Welcome" aria-label="Open Get Started">ILÉ</button>${[['Home','house'],['Menu','utensils'],['Reserve','calendar-days'],['Bag','shopping-bag'],['Account','user-round']].map(([n,i])=>`<button class="cursor-interaction" data-view="${n}" ${(view===n||(n==='Account'&&['Orders','Bookings','Favourites','Profile','Addresses','Notifications','Help'].includes(view)))?'aria-current="page"':''}>${I(i)}<span>${n==='Reserve'?'Book a table':n}</span>${n==='Bag'&&totalQty()?`<span class="navbadge">${totalQty()}</span>`:''}</button>`).join('')}</nav>`}
function pagehead(t,back='Home'){return `<div class="pagehead"><button class="icbutton cursor-interaction" data-view="${back}" aria-label="Back">${I('chevron-left')}</button><strong>${t}</strong><span class="mini dim">ILÉ</span></div>`}
function mealcard(m,large=false){return `<button class="meal cursor-interaction ${large?'large-meal':''}" data-dish="${m.id}" aria-label="View ${m.name}"><img src="${assets[m.img]}" alt="${m.name}"><div class="info"><div><h3>${m.short}</h3><p class="sub">${m.sub}</p></div><div class="pricebar"><span>${money(m.price)}</span><span class="plus">+</span></div></div></button>`}
function home(){return `<header class="homehead"><div class="topbar"><button class="wordmark cursor-interaction" data-view="Welcome" aria-label="Open Get Started">ILÉ</button><div class="homeplace">${I('map-pin')}<span>Victoria Island<br><strong>Lagos, Nigeria</strong></span></div><button class="icbutton cursor-interaction" data-action="saved" aria-label="Saved dishes">${I('heart')}</button></div></header><section class="homefeature"><div class="featurecopy"><h1>Jollof. Suya. Egusi.<br><span>Pull up a chair.</span></h1><p>From smoky party jollof to rich egusi.<br>Find your favourites, made fresh.</p><button class="primary cursor-interaction" data-view="Menu">Explore the menu ${I('arrow-right')}</button></div><img class="featurephoto" src="${assets.feast}" alt="Smoky jollof rice with grilled chicken skewers" width="760" height="507"></section><section class="section homekitchen">${foodCarousel(meals)}<button class="secondary cursor-interaction gallery-menu-link" data-view="Menu">View the full menu</button><button class="tablerow cursor-interaction" data-action="new-booking"><span class="tableicon">${I('calendar-days')}</span><span><strong>Bring your people.</strong><small>There’s a table for your next gathering.</small></span>${I('arrow-up-right')}</button><button class="textbutton cursor-interaction visitlink" data-view="Help">Location &amp; restaurant information</button></section>${nav()}`}

function menuItems(){const matches=meals.filter(m=>(category==='All'||m.cat===category)&&`${m.name} ${m.sub}`.toLowerCase().includes(query.toLowerCase()));if(!matches.length)return '<p class="empty">No dishes found. Try another name or category.</p>';const pics=matches.filter(m=>m.img),text=matches.filter(m=>!m.img);return `${pics.length?`<div class="pictured-menu">${pics.map(m=>mealcard(m,true)).join('')}</div>`:''}${text.length?`<div class="text-menu">${text.map(m=>`<button class="menudish cursor-interaction" data-dish="${m.id}" aria-label="View ${m.name}"><span><h3>${m.name}</h3><small>${m.sub}</small></span><span class="menudishend"><strong>${money(m.price)}</strong><span class="addcircle">${I('plus')}</span></span></button>`).join('')}</div>`:''}`}
function menu(){return `<div class="menu-screen"><section class="section"><div class="topbar"><span class="wordmark">ILÉ</span><button class="icbutton cursor-interaction" data-view="Bag" aria-label="Open your bag">${I('shopping-bag')}</button></div><h1 class="menutitle">Find your favourite.</h1><p class="description">Nigerian classics. Fresh from the kitchen.</p><label class="searchbox">${I('search')}<input id="ile-search" type="search" aria-label="Search the menu" placeholder="Search jollof, egusi, suya…"></label><div class="categories" aria-label="Menu categories">${['All','Rice','Soups','Grills','Sides','Drinks'].map(c=>`<button class="cursor-interaction" data-category="${c}" aria-pressed="${category===c}">${c}</button>`).join('')}</div><div id="ile-menu-items">${menuItems()}</div></section>${nav()}</div>`}
function dish(){const m=selected;return `${m.img?`<div class="dishphoto"><img src="${assets[m.img]}" alt="${m.name}"><button class="icbutton left cursor-interaction" data-view="Menu" aria-label="Back to menu">${I('chevron-left')}</button><button class="icbutton right cursor-interaction" data-action="save" aria-label="Save dish" aria-pressed="${saved.has(m.id)}" style="color:${saved.has(m.id)?'var(--ile-accent)':'var(--ile-ink)'}">${I('heart')}</button></div>`:pagehead('From our kitchen','Menu')}<section class="section"><div class="detailtag"><span>${m.cat==='Rice'?'A NIGERIAN FAVOURITE':m.cat.toUpperCase()}</span><span>Prepared fresh</span></div><div class="rowtitle" style="align-items:flex-start"><h1 class="detailname" style="margin-bottom:0">${m.name}</h1>${!m.img?`<button class="icbutton cursor-interaction" data-action="save" aria-label="Save dish" aria-pressed="${saved.has(m.id)}" style="color:var(--ile-accent);border-color:var(--ile-line)">${I('heart')}</button>`:''}</div><p class="description">${m.description}</p><div class="pricedetail">${money(m.price)}</div>${m.cat!=='Drinks'?`<fieldset><legend>Your pepper level</legend><div class="options">${['Mild','Medium','Hot'].map(h=>`<label><input type="radio" name="ile-heat" value="${h}" ${heat===h?'checked':''}>${h}</label>`).join('')}</div></fieldset>`:''}${m.cat==='Rice'?`<fieldset><legend>Make it your own</legend><label class="addrow"><img class="addonphoto" src="${assets.plantain}" alt="Golden fried ripe plantain"><span>Fried plantain <small>+ ₦1,500</small></span><input type="checkbox" id="ile-extra" ${extra?'checked':''}></label></fieldset>`:''}<p class="hint">${m.allergens}</p></section><div class="actionfoot"><div class="counter"><button class="cursor-interaction" data-action="minus" aria-label="Decrease quantity">−</button><span id="ile-quantity">${quantity}</span><button class="cursor-interaction" data-action="plus" aria-label="Increase quantity">+</button></div><button class="primary cursor-interaction" data-action="add" id="ile-add">Add · ${money((m.price+(extra?1500:0))*quantity)}</button></div>`}
const bookingSlots=['6:00 PM','6:30 PM','7:00 PM','7:30 PM','8:00 PM','8:30 PM'];
function availableSlots(date,now=Date.now()){return bookingSlots.filter(t=>{const [h,m]=t.split(' ')[0].split(':').map(Number);return Date.parse(`${date}T${String(h+12).padStart(2,'0')}:${String(m).padStart(2,'0')}:00+01:00`)>now})}
function nextBookingDate(){const d=new Date(currentDate+'T12:00:00Z');if(!availableSlots(currentDate).length)d.setUTCDate(d.getUTCDate()+1);return d.toISOString().slice(0,10)}
function reserve(){const times=availableSlots(draft.date);if(!times.includes(slot))slot=times[0]||'';return `${pagehead(editingBooking===null?'Reserve a table':'Change your table')}<div class="reservationintro"><span class="mini dim">VICTORIA ISLAND, LAGOS</span><h1 class="display">There’s a place<br>for your people.</h1><p>A quiet date, a birthday, or dinner with family.<br>Make yourself at home.</p></div><form id="ile-reservation" class="section"><div class="fieldgrid"><div><label class="labels" for="ile-date" style="margin-top:0">Date</label><input class="field" id="ile-date" type="date" value="${draft.date}" min="${currentDate}" required></div><div><label class="labels" for="ile-guests" style="margin-top:0">Guests</label><select class="field" id="ile-guests">${[1,2,3,4,5,6].map(n=>`<option ${draft.guests===n+' '+(n===1?'guest':'guests')?'selected':''}>${n} ${n===1?'guest':'guests'}</option>`).join('')}</select></div></div><fieldset><legend>Choose a time</legend><div class="times">${times.map(t=>`<button class="cursor-interaction" type="button" data-slot="${t}" aria-pressed="${slot===t}">${t}</button>`).join('')}</div>${!times.length?'<p class="hint">No sittings remain on this date. Choose a later date.</p>':''}</fieldset><fieldset><legend>Where would you like to sit?</legend><div class="seating"><label><input type="radio" name="ile-seat" value="Dining room" ${draft.seating==='Dining room'?'checked':''}>Dining room</label><label><input type="radio" name="ile-seat" value="Terrace" ${draft.seating==='Terrace'?'checked':''}>Terrace</label></div></fieldset><label class="labels" for="ile-name">Reservation name</label><input class="field" id="ile-name" autocomplete="name" placeholder="Your full name" required><label class="labels" for="ile-phone">Phone number</label><input class="field" id="ile-phone" type="tel" autocomplete="tel" placeholder="0801 234 5678" required pattern="[+0-9 ()-]{10,18}"><label class="labels" for="ile-occasion">Occasion <span style="color:var(--ile-muted);font-weight:400">(optional)</span></label><select class="field" id="ile-occasion">${['Just dinner','Birthday','Anniversary','Family gathering'].map(t=>`<option ${draft.occasion===t?'selected':''}>${t}</option>`).join('')}</select><p class="hint" style="margin:18px 0 21px">Demo booking · Try the complete reservation flow. No real table is reserved.</p><button class="primary wide cursor-interaction" type="submit" ${!times.length?'disabled':''}>${editingBooking===null?'Request my table':'Save reservation'}</button><p class="error" id="ile-reserve-error" role="alert"></p></form>${nav()}`}
function bagScreen(){return `${pagehead('Your bag','Menu')}<section class="section"><h1 class="detailname" style="margin:0">Your order.</h1>${bag.length?bag.map((b,i)=>`<div class="bagitem">${b.meal.img?`<img src="${assets[b.meal.img]}" alt="${b.meal.name}">`:`<div style="background:var(--ile-soft);border-radius:8px;display:grid;place-items:center">${I('utensils')}</div>`}<div><h3>${b.meal.name}</h3><p>${b.meal.cat==='Drinks'?'Chilled':b.heat+' pepper'}${b.extra?' · Plantain':''}</p><div class="bagbottom"><span>${money(b.unit*b.qty)}</span><div class="counter"><button class="cursor-interaction" data-bag="${i}" data-delta="-1" aria-label="Remove one ${b.meal.name}">−</button><span>${b.qty}</span><button class="cursor-interaction" data-bag="${i}" data-delta="1" aria-label="Add one ${b.meal.name}">+</button></div></div></div></div>`).join(''):'<p class="description" style="padding:25px 0">Your bag is empty. Add something from the kitchen.</p>'}<button class="textbutton cursor-interaction" data-view="Menu">+ Add another dish</button><div class="fulfilment" aria-label="Order collection method">${['Pickup','Delivery'].map(f=>`<button class="cursor-interaction" data-fulfil="${f}" aria-pressed="${fulfil===f}">${f}</button>`).join('')}</div><p class="description">${fulfil==='Pickup'?'Collect at ILÉ, Victoria Island.<br>Estimated preparation: 25-35 minutes.':'Deliver within Victoria Island.<br>Estimated arrival: 45-60 minutes.'}</p><label class="labels" for="ile-ordername">Name for your order</label><input class="field" id="ile-ordername" placeholder="Your full name" autocomplete="name"><label class="labels" for="ile-orderphone">Phone number</label><input class="field" id="ile-orderphone" type="tel" placeholder="0801 234 5678" autocomplete="tel">${fulfil==='Delivery'?'<button class="textbutton cursor-interaction" data-view="Addresses">Manage saved addresses</button><label class="labels" for="ile-address">Delivery address</label><textarea class="field" id="ile-address" placeholder="Street address, building and landmark" rows="2"></textarea>':''}<div class="summary"><p><span>Subtotal</span><span>${money(subtotal())}</span></p><p><span>${fulfil==='Pickup'?'Pickup':'Delivery'}</span><span>${fulfil==='Pickup'?'Free':money(2500)}</span></p><p class="total"><span>Total</span><span>${money(subtotal()+(fulfil==='Delivery'?2500:0))}</span></p></div><p class="hint" style="margin:8px 0 20px">Demo checkout · No sign-in or real payment required.</p><button class="primary wide cursor-interaction" data-action="order" ${!bag.length?'disabled':''}>Continue to checkout</button><p class="error" id="ile-order-error" role="alert"></p></section>${nav()}`}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let profile={name:'',phone:'',email:''},signedIn=true,authPhone='',payment='Pay on collection',orderNotes='',selectedOrder=0,selectedBooking=0,editingBooking=null,editingAddress=null,cancelTarget=null,orderFilter='All',activeFaq=null;
let addresses=[],preferences={orders:true,bookings:true,offers:false};
const orders=[],bookings=[];
function blank(icon,title,copy,target,label){return `<div class="blank"><div class="blankicon">${I(icon)}</div><h2>${title}</h2><p class="description">${copy}</p>${target?`<button class="primary wide cursor-interaction" data-view="${target}">${label}</button>`:''}</div>`}
function titleblock(kicker,title,copy){return `<div class="titleblock"><span class="mini">${kicker}</span><h1 class="display">${title}</h1>${copy?`<p class="description">${copy}</p>`:''}</div>`}
function rowLink(icon,label,sub,target){return `<button class="accountrow cursor-interaction" data-view="${target}"><span class="rowicon">${I(icon)}</span><span class="rowcopy"><strong>${label}</strong>${sub?`<small>${sub}</small>`:''}</span>${I('chevron-right')}</button>`}
function dateText(d){return new Date(d+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'})}
function favourites(){const favs=meals.filter(m=>saved.has(m.id));return `${pagehead('Your favourites')}<section class="section">${titleblock('KEEP THE GOOD ONES','Always a favourite.','Your saved dishes, ready when you are.')}${favs.length?favs.map(m=>`<div class="favouriterow">${m.img?mealcard(m,true):`<button class="listdish cursor-interaction" data-dish="${m.id}"><span><strong>${m.name}</strong><small>${m.sub}</small></span><span>${money(m.price)}</span></button>`}<button class="textbutton cursor-interaction" data-unsave="${m.id}">Remove from favourites</button></div>`).join(''):blank('heart','A place for your favourites','Tap the heart on any dish to keep it here.','Menu','Explore the menu')}</section>${nav()}`}
function welcome(){return `<section class="getstarted"><header class="starthead"><span class="animated-brand" aria-label="ILÉ"><iframe class="logo-motion" src="/motion/ile-logo/index.html?autoplay=1" title="Animated ILÉ logo" tabindex="-1"></iframe></span><span class="startlocation">Nigerian kitchen & table</span></header><div class="startimage"><img src="${assets.jollof}" alt="Smoky Nigerian jollof rice served with grilled chicken skewers" fetchpriority="high" width="760" height="507"></div><div class="startcopy"><h1>A Nigerian table.<br><span>Made for you.</span></h1><p>Smoky jollof, rich egusi, fresh suya.<br>Nigerian favourites, from our kitchen to your table.</p><button class="primary startcta cursor-interaction" data-action="get-started">Get started ${I('arrow-right')}</button><button class="signin-secondary startsignin" data-view="Sign in">Sign in</button></div></section>${foodCarousel(meals,'Meet your next favourite')}`}
function checkout(){const total=subtotal()+(fulfil==='Delivery'?2500:0);return `${pagehead('Checkout','Bag')}<section class="section">${titleblock('THE FINAL DETAILS','A good meal<br>is almost yours.','Review your demo order before confirming.')}<div class="checkoutdetail"><div class="inline">${I(fulfil==='Pickup'?'store':'map-pin')}<strong>${fulfil==='Pickup'?'Collect from ILÉ':'Deliver to you'}</strong></div><p>${fulfil==='Pickup'?'Victoria Island, Lagos':esc(address)}</p><p>${esc(orderName)} · ${esc(orderPhone)}<br> ${fulfil==='Pickup'?'25-35':'45-60'} minutes</p><button class="textbutton cursor-interaction" data-view="Bag">Change details</button></div><fieldset><legend>How would you like to pay?</legend><div class="payoptions">${['Pay on '+(fulfil==='Pickup'?'collection':'delivery')].map(p=>`<label><span class="inline">${I(p==='Card'?'credit-card':'wallet')}<span><strong>${p}</strong><small>${p==='Card'?'Secure card payment':'Cash or POS when your meal arrives'}</small></span></span><input type="radio" name="ile-payment" value="${p}" ${payment===p?'checked':''}></label>`).join('')}</div></fieldset>${payment==='Card'?'<p class="hint">Card payments are not yet connected.</p>':''}<label class="labels" for="ile-notes">A note for the kitchen <span class="dimlabel">(optional)</span></label><textarea class="field" id="ile-notes" rows="2" placeholder="Any special requests?"></textarea><div class="orderlines">${bag.map(b=>`<p><span>${b.qty} × ${b.meal.name}</span><span>${money(b.unit*b.qty)}</span></p>`).join('')}</div><div class="summary"><p><span>Subtotal</span><span>${money(subtotal())}</span></p><p><span>${fulfil}</span><span>${fulfil==='Pickup'?'Free':money(2500)}</span></p><p class="total"><span>Total</span><span>${money(total)}</span></p></div><p class="hint" style="margin-bottom:20px">Demo checkout · No payment is collected and no order is sent to the restaurant.</p><button class="primary wide cursor-interaction" data-action="place-order" ${!bag.length?'disabled':''}>${payment==='Card'?'Pay':'Place order'} · ${money(total)}</button><p id="ile-checkout-error" class="error" role="alert"></p></section>`}
function orderSteps(o){return o.fulfil==='Pickup'?['Order received','In the kitchen','Ready to collect','Collected']:['Order received','In the kitchen','Out for delivery','Delivered']}
function tracking(){const o=orders[selectedOrder];if(!o)return `${pagehead('Your order','Orders')}<section class="section">${blank('receipt','Nothing cooking yet','Your next order will appear here.','Menu','Explore the menu')}</section>`;const steps=orderSteps(o);return `${pagehead('Your order','Orders')}<section class="section">${titleblock(esc(o.reference||o.id),steps[o.status],o.status===3?'Thanks for making ILÉ part of your day.':o.fulfil==='Pickup'?'Follow your order’s latest kitchen updates.':'Follow your order’s latest delivery updates.')}<div class="eta"><span>${o.status===3?'Completed':o.status===2?(o.fulfil==='Pickup'?'Collection':'Delivery estimate'):'Estimated '+(o.fulfil==='Pickup'?'collection':'arrival')}</span><strong>${o.status===3?dateText(o.date):(o.fulfil==='Pickup'?'25-35 min':'45-60 min')}</strong></div><ol class="timeline">${steps.map((s,i)=>`<li class="${i<=o.status?'done':''}"><span class="stepdot">${i<o.status?I('check'):i+1}</span><div><strong>${s}</strong><small>${['Your order has been received.','Freshly cooked, just for you.',o.fulfil==='Pickup'?'Your meal will be waiting at ILÉ.':'Our rider is bringing your meal.','Enjoy every bite.'][i]}</small></div></li>`).join('')}</ol><div class="checkoutdetail"><div class="inline">${I(o.fulfil==='Pickup'?'store':'map-pin')}<strong>${o.fulfil==='Pickup'?'Pickup at ILÉ':esc(o.address)}</strong></div><p>${esc(o.name)} · ${o.payment==='Card'?'Paid by card':o.payment}</p></div><div class="orderlines">${o.items.map(b=>`<p><span>${b.qty} × ${b.meal.name}</span><span>${money(b.unit*b.qty)}</span></p>`).join('')}</div><div class="summary"><p class="total"><span>Total</span><span>${money(o.total)}</span></p></div>${o.notes?`<p class="hint">Kitchen note: ${esc(o.notes)}</p>`:''}<button class="secondary cursor-interaction" data-view="Help" style="margin-top:20px">Need a hand with this order?</button>${o.status===3?`<button class="primary wide cursor-interaction" data-reorder="${selectedOrder}" style="margin-top:12px">Order these again</button>`:''}</section>${nav()}`}
function orderHistory(){return `${pagehead('Your orders','Account')}<section class="section">${titleblock('FROM OUR KITCHEN','Good meals,<br>good memories.','Your recent orders, all in one place.')}<div class="fulfilment">${['All','In progress','Completed'].map(f=>`<button class="cursor-interaction" data-order-filter="${f}" aria-pressed="${orderFilter===f}">${f}</button>`).join('')}</div>${orders.map((o,i)=>({o,i})).filter(({o})=>orderFilter==='All'||(orderFilter==='Completed'?o.status===3:o.status<3)).reverse().map(({o,i})=>`<article class="historycard"><div class="historytop"><span class="mini">${esc(o.reference||o.id)}</span><span class="statuspill">${orderSteps(o)[o.status]}</span></div><h2>${o.items[0].meal.name}${o.items.length>1?` + ${o.items.length-1} more`:''}</h2><p>${dateText(o.date)} · ${o.fulfil}</p><div class="historybottom"><strong>${money(o.total)}</strong><button class="textbutton cursor-interaction" data-order="${i}">View order ${I('arrow-up-right')}</button></div>${o.status===3?`<button class="secondary cursor-interaction" data-reorder="${i}">Order again</button>`:''}</article>`).join('')||blank('receipt','No orders here yet','Find a favourite and let us do the cooking.','Menu','Explore the menu')}</section>${nav()}`}
function bookingList(){return `${pagehead('Your tables','Account')}<section class="section">${titleblock('A PLACE FOR YOUR PEOPLE','Something to<br>look forward to.','Your reservations at ILÉ, Victoria Island.')}<button class="primary wide cursor-interaction" data-action="new-booking">Book a table</button><div class="bookinglist">${bookings.map((b,i)=>({b,i})).reverse().map(({b,i})=>`<button class="bookingcard cursor-interaction" data-booking="${i}"><div class="bookingdate"><strong>${new Date(b.date+'T12:00:00').getDate()}</strong><span>${new Date(b.date+'T12:00:00').toLocaleDateString('en-GB',{month:'short'})}</span></div><div><span class="statuspill ${b.status==='Cancelled'?'cancelled':''}">${b.status}</span><h2>${b.slot} · ${b.guests}</h2><p>${b.seating} · Victoria Island</p></div>${I('chevron-right')}</button>`).join('')||blank('calendar-days','Your next gathering starts here','Choose a date and bring your people.','Reserve','Reserve a table')}</div></section>${nav()}`}
function bookingDetails(){const b=bookings[selectedBooking];if(!b)return `${pagehead('Reservation','Bookings')}<section class="section">${blank('calendar-days','No reservation selected','Book a table for your next visit.','Reserve','Book a table')}</section>`;return `${pagehead('Your reservation','Bookings')}<section class="section">${titleblock(b.status==='Cancelled'?'RESERVATION CANCELLED':b.status.toUpperCase(),b.status==='Cancelled'?'Until next time.':'Your table<br>at ILÉ.',b.status==='Cancelled'?'You can always book another table.':'Your request details, all in one place.')}<div class="ticket"><div class="ticketlogo"><div class="wordmark">ILÉ</div><p>Victoria Island, Lagos</p></div><dl>${[['Date',dateText(b.date)],['Time',b.slot],['Guests',b.guests],['Seating',b.seating],['Under the name',b.name],['Occasion',b.occasion]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><p class="ref">${esc(b.reference||b.id)}</p></div><p class="hint" style="margin-bottom:22px">Table requests need restaurant confirmation. Once confirmed, please arrive within 15 minutes of your booking. Changes need a fresh confirmation.</p>${b.status!=='Cancelled'?`<button class="primary wide cursor-interaction" data-action="edit-booking">Change reservation</button><button class="textbutton cursor-interaction" data-view="Cancel booking">Cancel reservation</button>`:`<button class="primary wide cursor-interaction" data-action="new-booking">Book another table</button>`}</section>`}
function cancelBooking(){const b=bookings[selectedBooking];return `${pagehead('Cancel reservation','Booking details')}<section class="section">${titleblock('A CHANGE OF PLANS','Let this<br>table go?','Cancelling closes this table request. You can book again whenever you’re ready.')}<div class="checkoutdetail"><strong>${b?`${dateText(b.date)} · ${b.slot}`:'No reservation selected'}</strong><p>${b?esc(b.guests+' · '+b.seating):''}</p></div><button class="primary wide cursor-interaction" data-action="keep-booking">Keep my reservation</button><button class="secondary cursor-interaction" data-action="cancel-booking" style="margin-top:12px">Yes, cancel this table</button></section>`}
function account(){return `${pagehead('Your ILÉ')}<section class="section">${titleblock('MAKE YOURSELF AT HOME',signedIn?`Hello, ${esc(profile.name.split(' ')[0]||'there')}.`:'Welcome to ILÉ.',signedIn?'Demo access is active. Your favourites, orders and tables are saved on this device.':'Explore the menu and build your bag as a guest. Saved accounts, orders and reservations require a connected sign-in service.')}${signedIn?`<div class="profilechip"><span class="avatar">${esc((profile.name||'You').charAt(0).toUpperCase())}</span><div><strong>${esc(profile.name||'Your profile')}</strong><small>${esc(profile.phone)}</small></div><button class="textbutton cursor-interaction" data-view="Profile">Edit</button></div>`:`<button class="primary wide" data-view="Sign in" style="margin-bottom:22px">Sign in</button>`}<div class="accountgroup">${rowLink('receipt','Your orders','Track a meal or order it again','Orders')}${rowLink('calendar-days','Your tables','View and manage reservations','Bookings')}${rowLink('heart','Favourites',`${saved.size} saved ${saved.size===1?'dish':'dishes'}`,'Favourites')}</div><div class="accountgroup">${rowLink('map-pin','Saved addresses','Your usual places in Lagos','Addresses')}${rowLink('bell','Notifications','Choose what you hear from us','Notifications')}${rowLink('circle-help','Help & information','A hand with your visit or order','Help')}</div><button class="textbutton" data-view="Sign in">View demo sign-in</button>${isStaff?rowLink('clipboard-list','Restaurant console','Manage orders and table requests','Operations'):''}<p class="hint">ILÉ · Nigerian kitchen & table</p></section>${nav()}`}
function profileScreen(){return `${pagehead('Your profile','Account')}<section class="section">${titleblock('THE SMALL DETAILS','Let’s make it<br>personal.','Tell us what to call you when your table is ready.')}<form id="ile-profile"><label class="labels" for="ile-profile-name">Full name</label><input class="field" id="ile-profile-name" autocomplete="name" required placeholder="Your full name"><label class="labels" for="ile-profile-phone">Phone number</label><input class="field" id="ile-profile-phone" autocomplete="tel" type="tel" required placeholder="+234 801 234 5678"><label class="labels" for="ile-profile-email">Email <span class="dimlabel">(optional)</span></label><input class="field" id="ile-profile-email" autocomplete="email" type="email" placeholder="you@example.com"><button class="primary wide cursor-interaction" type="submit" style="margin-top:28px">Save details</button><p class="error" id="ile-profile-error" role="alert"></p></form></section>`}
function addressList(){return `${pagehead('Saved addresses','Account')}<section class="section">${titleblock('YOUR CORNER OF LAGOS','The places<br>you call home.','Save an address for a quicker checkout. Delivery in this concept covers Victoria Island.')} ${addresses.map((a,i)=>`<div class="addresscard"><div class="inline">${I(a.label==='Work'?'briefcase-business':'house')}<strong>${esc(a.label)}</strong>${a.primary?'<span class="statuspill">Default</span>':''}</div><p>${esc(a.street)}</p><small>${esc(a.landmark)}</small><div class="addressactions"><button class="textbutton cursor-interaction" data-address="${i}">Edit</button>${!a.primary?`<button class="textbutton cursor-interaction" data-default-address="${i}">Make default</button>`:''}<button class="textbutton cursor-interaction" data-remove-address="${i}">Remove</button>${bag.length?`<button class="textbutton cursor-interaction" data-use-address="${i}">Use for delivery</button>`:''}</div></div>`).join('')||blank('map-pin','Where should we bring it?','Your saved addresses will appear here.')}<button class="primary wide cursor-interaction" data-action="new-address">Add an address</button></section>`}
function addressForm(){const a=addresses[editingAddress]||{label:'Home',street:'',landmark:''};return `${pagehead(editingAddress===null?'Add an address':'Edit address','Addresses')}<section class="section">${titleblock('VICTORIA ISLAND, LAGOS','We’ll find<br>our way to you.','A building name or landmark helps your rider arrive smoothly.')}<form id="ile-addressform"><label class="labels" for="ile-address-label">Address label</label><select class="field" id="ile-address-label">${['Home','Work','Other'].map(l=>`<option ${a.label===l?'selected':''}>${l}</option>`).join('')}</select><label class="labels" for="ile-address-street">Street & building</label><textarea class="field" id="ile-address-street" rows="3" required placeholder="Street address, flat or building number"></textarea><label class="labels" for="ile-landmark">Landmark <span class="dimlabel">(optional)</span></label><input class="field" id="ile-landmark" placeholder="Near…"><label class="addrow"><span>Use as my default address</span><input type="checkbox" id="ile-address-primary" ${a.primary||!addresses.length?'checked':''}></label><button class="primary wide cursor-interaction" type="submit" style="margin-top:24px">Save address</button><p class="error" id="ile-address-error" role="alert"></p></form></section>`}
function notifications(){return `${pagehead('Notifications','Account')}<section class="section">${titleblock('KEEP IN TOUCH','Only the things<br>you care about.','Choose your updates from ILÉ.')} ${[['orders','Order updates','Preparation, collection and delivery.'],['bookings','Table reminders','A reminder before your reservation.'],['offers','News from the kitchen','New dishes and occasional offers.']].map(([k,t,d])=>`<label class="settingrow"><span><strong>${t}</strong><small>${d}</small></span><input type="checkbox" class="toggleswitch" data-pref="${k}" ${preferences[k]?'checked':''}></label>`).join('')}<p class="hint">Preferences are saved to your account. Order and booking updates appear in the app; text and email notifications are not yet connected.</p></section>`}
const faqs=[['Where is ILÉ?','ILÉ is a restaurant app concept in Victoria Island, Lagos. The exact address and contact details will be added before public launch.'],['Can you cater for allergies?','Discuss dietary requirements with the restaurant before ordering. Suya contains groundnuts. The concept egusi and efo riro recipes contain fish and shellfish.'],['How do collection and delivery work?','Pickup is estimated at 25-35 minutes. Victoria Island delivery is estimated at 45-60 minutes, with a ₦2,500 fee. The restaurant must approve the final service area and timings.'],['Can I change my reservation?','Open Your tables, select your request and choose Change reservation. Changes return it to Requested until the restaurant confirms.'],['How are payments handled?','Pay on collection or delivery. No card charge is taken through this app. Orders and table requests are saved to your account; this app is not yet connected to a trading restaurant.']];
function help(){return `${pagehead('Help & information','Account')}<section class="section">${titleblock('WE’RE HERE FOR YOU','A little help<br>from the host.','Answers before you order or take a seat.')}<div class="helpintro"><span class="rowicon">${I('messages-square')}</span><div><strong>Speak to the ILÉ team</strong><p>Victoria Island, Lagos</p></div></div><dl class="venuefacts"><div><dt>Street address</dt><dd>Awaiting restaurant details</dd></div><div><dt>Opening hours</dt><dd>Awaiting restaurant details</dd></div><div><dt>Phone &amp; WhatsApp</dt><dd>Awaiting restaurant details</dd></div></dl><div class="helpintro"><div><p>Orders and bookings are demonstration requests until the restaurant is connected.</p></div></div><div class="faqs">${faqs.map(([t,d],i)=>`<div class="faq"><button class="cursor-interaction" data-faq="${i}" aria-expanded="${activeFaq===i}"><span>${t}</span>${I(activeFaq===i?'minus':'plus')}</button>${activeFaq===i?`<p>${d}</p>`:''}</div>`).join('')}</div></section>`}

function confirmed(){const b=booking||bookings[selectedBooking];if(!b)return `${pagehead('Confirmation')}<section class="section">${blank('check','Ready when you are','Place an order or reserve a table to see your confirmation.','Home','Back to home')}</section>`;return `${pagehead(b.type==='order'?'Order received':'You’re booked')}<section class="success"><div class="checkmark">${I('check')}</div><span class="mini" style="color:var(--ile-accent)">${b.type==='order'?'ORDER SAVED':'A PLACE FOR YOUR PEOPLE'}</span><h1 class="display">${b.type==='order'?'Your demo order<br>is saved.':'Your demo table<br>request is in.'}</h1><p class="description">${b.type==='order'?'Your demo order is saved on this device. No payment was taken.':'Your demo reservation is saved on this device. No real table is reserved.'}</p><div class="ticket"><div class="ticketlogo"><div class="wordmark">ILÉ</div><p>Nigerian kitchen & table · Lagos</p></div><dl>${(b.type==='order'?[['Order method',b.fulfil],['Estimated time',b.fulfil==='Pickup'?'25-35 minutes':'45-60 minutes'],['Total',money(b.total)],['Payment',b.payment==='Card'?'Paid by card':b.payment]]:[['Date',dateText(b.date)],['Time',b.slot],['Guests',b.guests],['Seating',b.seating]]).map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}<div style="grid-column:1/-1"><dt>Under the name</dt><dd>${esc(b.name)}</dd></div></dl><p class="ref">${esc(b.reference||b.id)}</p></div><p class="hint" style="margin:0 0 23px">${b.type==='order'?'Keep your reference handy for collection or delivery.':'View your reservation to check its confirmation status.'}</p><button class="primary wide cursor-interaction" data-view="${b.type==='order'?'Tracking':'Booking details'}">${b.type==='order'?'Track my order':'View my reservation'}</button><button class="textbutton cursor-interaction" data-view="Home" style="margin-top:12px">Back to home</button></section>${nav()}`}
const viewFns={Home:home,Menu:menu,Dish:dish,Reserve:reserve,Bag:bagScreen,Confirmed:confirmed,Favourites:favourites,Welcome:welcome,Checkout:checkout,Tracking:tracking,Orders:orderHistory,Bookings:bookingList,'Booking details':bookingDetails,'Cancel booking':cancelBooking,Account:account,Profile:profileScreen,Addresses:addressList,'Add address':addressForm,Notifications:notifications,Help:help,Operations:operations};
function fill(id,value){const n=app.querySelector('#'+id);if(n)n.value=value||''}
function icons(){root.querySelectorAll('i[data-lucide]').forEach(el=>{const Icon=iconMap[el.dataset.lucide];if(Icon)el.outerHTML=renderToStaticMarkup(createElement(Icon,{className:'ic',width:20,height:20,strokeWidth:1.7,'aria-hidden':true}));})}

let gateReturn='Account',remembered=false;
const protectedViews=['Orders','Tracking','Bookings','Booking details','Cancel booking','Profile','Addresses','Add address','Notifications','Operations','Favourites'];
function signInGate(){const entry=view==='Sign in';return `${pagehead(entry?'Welcome to ILÉ':'Your ILÉ')}<section class="signin-screen"><div class="signin-copy"><span class="wordmark signin-brand" aria-label="ILÉ">ILÉ</span><span class="eyebrow">YOUR PLACE AT THE TABLE</span><h1>Come on in.<br><span>Make yourself at home.</span></h1><p>${entry?'Smoky jollof, rich egusi, fresh suya.<br>Your next favourite is waiting.':'You’re browsing as a guest. Saving favourites, placing orders and managing reservations will be available when account sign-in is connected.'}</p><div class="signin-options"><button class="google-signin cursor-interaction" data-action="demo-signin"><img src="/brand/google-g.png" alt="" width="20" height="20">Continue with Google</button><div class="signin-divider">or</div><button class="primary email-signin cursor-interaction" data-action="demo-signin">${I('mail')} Continue with email</button></div><p class="signin-security">Demo access · No account or password needed.</p><button class="signin-guest" data-view="Menu">Go straight to the menu</button></div><div class="signin-photo"><img src="${assets.suya}" alt="Nigerian beef suya with fresh tomatoes and onions"><div><span class="eyebrow">GOOD FOOD. GOOD COMPANY.</span><strong>There’s always<br>room for you.</strong></div></div></section>`}
viewFns['Sign in']=signInGate;
let demoEntryTimer, demoEntryLoading=false;
function enterDemo(){if(demoEntryLoading)return;demoEntryLoading=true;root.dataset.view='Loading';app.innerHTML=`<section class="auth-loader" role="status" aria-live="polite" aria-label="Opening ILÉ"><span class="auth-loading-brand" aria-label="ILÉ"><span>IL</span><span>É</span></span><span class="auth-loading-line" aria-hidden="true"></span><p>Getting your table ready…</p></section>`;demoEntryTimer=setTimeout(()=>{if(controller.signal.aborted)return;demoEntryLoading=false;try{localStorage.setItem('ile-welcome-v2','seen')}catch{}go('Home')},1100)}
let busy=false,isStaff=false,orderPhone='',orderKey=crypto.randomUUID(),bookingKey=crypto.randomUUID(),loaded=false,opsOrders=[],opsBookings=[];
const storageKey='ile-bag-v1';
function remember(){capture();try{sessionStorage.setItem('ile-resume',JSON.stringify({orderName,orderPhone,address,orderNotes,fulfil,draft,slot}))}catch{}}
try{const r=JSON.parse(sessionStorage.getItem('ile-resume')||'null');if(r&&typeof r==='object'){for(const [key,set] of [['orderName',v=>orderName=v],['orderPhone',v=>orderPhone=v],['address',v=>address=v],['orderNotes',v=>orderNotes=v]])if(typeof r[key]==='string')set(r[key]);if(['Pickup','Delivery'].includes(r.fulfil))fulfil=r.fulfil;if(r.draft&&/^\d{4}-\d{2}-\d{2}$/.test(r.draft.date)){draft={...draft,...r.draft};remembered=true}if(['6:00 PM','6:30 PM','7:00 PM','7:30 PM','8:00 PM','8:30 PM'].includes(r.slot))slot=r.slot;payment='Pay on '+(fulfil==='Pickup'?'collection':'delivery')}}catch{}
try{const local=JSON.parse(localStorage.getItem(storageKey)||'[]');if(Array.isArray(local))bag=local.map(b=>{const meal=meals.find(m=>m.id===b.id);return meal&&Number.isInteger(b.qty)&&b.qty>0&&b.qty<=20?{meal,qty:b.qty,heat:['Mild','Medium','Hot'].includes(b.heat)?b.heat:'Medium',extra:meal.cat==='Rice'&&!!b.extra,unit:meal.price+(meal.cat==='Rice'&&b.extra?1500:0)}:null}).filter(Boolean)}catch{}
function saveBag(){try{localStorage.setItem(storageKey,JSON.stringify(bag.map(b=>({id:b.meal.id,qty:b.qty,heat:b.heat,extra:b.extra}))))}catch{}}
const demoStorageKey='ile-demo-account-v1';
const demoDefaults=()=>({profile:{name:'Demo guest',phone:'',email:''},favourites:[],preferences:{orders:true,bookings:true,offers:false},addresses:[],orders:[],bookings:[]});
let demoState=demoDefaults();
try{const value=JSON.parse(localStorage.getItem(demoStorageKey)||'null');if(value&&typeof value==='object'){demoState={...demoState,...value};for(const key of ['favourites','addresses','orders','bookings'])if(!Array.isArray(demoState[key]))demoState[key]=[];demoState.profile={...demoDefaults().profile,...demoState.profile};demoState.preferences={...demoDefaults().preferences,...demoState.preferences}}}catch{}
function saveDemo(){try{localStorage.setItem(demoStorageKey,JSON.stringify(demoState))}catch{}}
async function api(path,method='GET',data){
 if(path==='state')return {authenticated:true,menu:[...meals],today:currentDate,...demoState,staff:false};
 if(path==='account'){if(data.profile)demoState.profile={...demoState.profile,...data.profile};if(data.favourites)demoState.favourites=data.favourites;if(data.preferences)demoState.preferences=data.preferences;saveDemo();return {ok:true}}
 if(path==='addresses'&&method==='DELETE'){demoState.addresses=demoState.addresses.filter(a=>a.id!==data.id);saveDemo();return {ok:true}}
 if(path==='addresses'){const item={...data,id:data.id||crypto.randomUUID()};if(item.primary)demoState.addresses.forEach(a=>a.primary=false);const i=demoState.addresses.findIndex(a=>a.id===item.id);if(i<0)demoState.addresses.push(item);else demoState.addresses[i]=item;saveDemo();return {ok:true}}
 if(path==='orders'&&method==='POST'){
 const old=demoState.orders.find(o=>o.idempotencyKey===data.idempotencyKey);if(old)return {order:old};
 const items=data.items.map(b=>{const meal=meals.find(m=>m.id===b.id);if(!meal)throw new Error('Choose a dish from the menu.');return {...b,meal,unit:meal.price+(b.extra?1500:0)}});
 const sub=items.reduce((sum,b)=>sum+b.unit*b.qty,0),delivery=data.fulfil==='Delivery'?2500:0,id=crypto.randomUUID();
 const order={...data,id,reference:'DEMO-'+id.slice(0,8).toUpperCase(),type:'order',items,subtotal:sub,delivery,total:sub+delivery,status:0,payment:'Pay on '+(data.fulfil==='Pickup'?'collection':'delivery'),date:currentDate};demoState.orders.push(order);saveDemo();return {order};
 }
 if(path==='bookings'){
 const i=demoState.bookings.findIndex(b=>b.id===data.id);
 if(data.cancel){if(i<0)throw new Error('Select a reservation.');demoState.bookings[i].status='Cancelled';saveDemo();return {booking:demoState.bookings[i]}}
 const old=demoState.bookings.find(b=>data.idempotencyKey&&b.idempotencyKey===data.idempotencyKey);if(old)return {booking:old};
 const id=data.id||crypto.randomUUID(),record={...data,id,reference:i>=0?demoState.bookings[i].reference:'DEMO-T'+id.slice(0,7).toUpperCase(),type:'reservation',guests:data.guests+' guests',status:'Requested'};
 if(i>=0)demoState.bookings[i]=record;else demoState.bookings.push(record);saveDemo();return {booking:record};
 }
 throw new Error('This action is not available in the demo.');
}
async function refresh(shouldRender=true){const data=await api('state');const orderId=orders[selectedOrder]?.id,bookingId=bookings[selectedBooking]?.id;signedIn=data.authenticated===true;profile=data.profile;saved=new Set(data.favourites);preferences=data.preferences;addresses=data.addresses;meals.splice(0,meals.length,...data.menu);orders.splice(0,orders.length,...data.orders);bookings.splice(0,bookings.length,...data.bookings);if(orderId){const i=orders.findIndex(o=>o.id===orderId);if(i>=0)selectedOrder=i}if(bookingId){const i=bookings.findIndex(b=>b.id===bookingId);if(i>=0)selectedBooking=i}if(!loaded){currentDate=data.today;if(!remembered){draft.date=nextBookingDate();draft.name=profile.name;draft.phone=profile.phone}orderName=orderName||profile.name;orderPhone=orderPhone||profile.phone;loaded=true}isStaff=data.staff;if(shouldRender)render();return data}
async function mutate(task){if(busy)return;busy=true;app.setAttribute('aria-busy','true');app.dataset.busy='true';note('Saving…');try{await task()}catch(e){if(e.name!=='AbortError')note(e.message||'Could not save. Please try again.')}finally{busy=false;app.setAttribute('aria-busy','false');delete app.dataset.busy}}
let animatedView='',pointerMotion=true;
listen('pointerdown',()=>{pointerMotion=true});
listen('keydown',()=>{pointerMotion=false});
function motion(el,frames,duration=240){if(!pointerMotion||typeof matchMedia!=='function'||matchMedia('(prefers-reduced-motion: reduce)').matches||typeof el?.animate!=='function')return;el.animate(frames,{duration,easing:'cubic-bezier(.23,1,.32,1)'})}
function animateScreen(){if(animatedView===view)return;animatedView=view;motion(app,[{opacity:.85,transform:'translateY(6px)'},{opacity:1,transform:'translateY(0)'}]);}

function render(){if(demoEntryLoading)return;root.dataset.view=view;app.dataset.screen=view;if(!signedIn&&protectedViews.includes(view)){gateReturn=view;app.innerHTML=signInGate()}else app.innerHTML=(viewFns[view]||home)();if(view==='Menu')fill('ile-search',query);if(view==='Reserve'){fill('ile-name',draft.name);fill('ile-phone',draft.phone)}if(view==='Bag'){fill('ile-ordername',orderName);fill('ile-orderphone',orderPhone);fill('ile-address',address)}if(view==='Checkout')fill('ile-notes',orderNotes);if(view==='Profile'){fill('ile-profile-name',profile.name);fill('ile-profile-phone',profile.phone);fill('ile-profile-email',profile.email)}if(view==='Add address'){const a=addresses[editingAddress];fill('ile-address-street',a?.street);fill('ile-landmark',a?.landmark)}icons();saveBag();animateScreen();engagement?.refreshCarousel()}
function capture(){if(view==='Reserve'){for(const [k,id] of [['name','ile-name'],['phone','ile-phone'],['date','ile-date'],['guests','ile-guests'],['occasion','ile-occasion']])draft[k]=app.querySelector('#'+id)?.value||'';draft.seating=app.querySelector('[name="ile-seat"]:checked')?.value||'Dining room'}if(view==='Bag'){orderName=app.querySelector('#ile-ordername')?.value||'';orderPhone=app.querySelector('#ile-orderphone')?.value||'';address=app.querySelector('#ile-address')?.value||address}if(view==='Checkout')orderNotes=app.querySelector('#ile-notes')?.value||''}
function go(v){capture();view=v;note('');render();try{history.pushState({view:v},'',v==='Home'?'/':'/#'+encodeURIComponent(v))}catch{}app.scrollIntoView({behavior:'instant',block:'start'});if(['Orders','Bookings','Tracking'].includes(v))refresh().catch(e=>note(e.message));if(v==='Operations')loadOperations()}
function updatePrice(){app.querySelector('#ile-quantity').textContent=quantity;motion(app.querySelector('#ile-quantity'),[{transform:'scale(1.08)'},{transform:'scale(1)'}],160);app.querySelector('#ile-add').textContent='Add · '+money((selected.price+(extra?1500:0))*quantity)}
function resetBooking(){editingBooking=null;bookingKey=crypto.randomUUID();draft={date:nextBookingDate(),guests:'2 guests',name:profile.name,phone:profile.phone,seating:'Dining room',occasion:'Just dinner'};slot='7:00 PM';go('Reserve')}
function validPhone(p){return /^(?:\+?234|0)[789][01]\d{8}$/.test(p.replace(/[\s()-]/g,''))}
function orderInput(){return {idempotencyKey:orderKey,name:orderName.trim(),phone:orderPhone.trim(),fulfil,address,notes:orderNotes,items:bag.map(b=>({id:b.meal.id,qty:b.qty,heat:b.heat,extra:b.extra}))}}
function bookingInput(){return {name:draft.name.trim(),phone:draft.phone.trim(),date:draft.date,guests:parseInt(draft.guests,10),slot,seating:draft.seating,occasion:draft.occasion}}
listen('click',e=>{const b=e.target.closest('button');if(!b||!root.contains(b)||b.disabled||busy)return;const d=b.dataset;if(d.view){go(d.view);return}if(d.dish){capture();selected=meals.find(m=>m.id===d.dish);if(!selected)return;quantity=1;extra=false;heat='Medium';go('Dish');return}if(d.category){category=d.category;render();motion(app.querySelector('#ile-menu-items'),[{opacity:.75,transform:'translateY(4px)'},{opacity:1,transform:'translateY(0)'}],200);return}if(d.slot){slot=d.slot;app.querySelectorAll('[data-slot]').forEach(t=>t.setAttribute('aria-pressed',String(t===b)));return}if(d.fulfil){capture();fulfil=d.fulfil;payment='Pay on '+(fulfil==='Pickup'?'collection':'delivery');if(fulfil==='Delivery'&&!address){const a=addresses.find(a=>a.primary)||addresses[0];if(a)address=a.street+(a.landmark?', '+a.landmark:'')}render();return}if(d.bag!==undefined){capture();const i=Number(d.bag);if(bag[i])bag[i].qty=Math.max(0,Math.min(20,bag[i].qty+Number(d.delta)));bag=bag.filter(x=>x.qty>0);orderKey=crypto.randomUUID();render();return}if(d.unsave){const next=[...saved].filter(id=>id!==d.unsave);mutate(async()=>{await api('account','PATCH',{favourites:next});await refresh();note('Removed from favourites.')});return}if(d.order!==undefined){selectedOrder=Number(d.order);go('Tracking');return}if(d.reorder!==undefined){bag=orders[Number(d.reorder)].items.map(b=>({...b}));orderKey=crypto.randomUUID();go('Bag');note('Review your dishes and contact details before checkout.');return}if(d.orderFilter){orderFilter=d.orderFilter;render();return}if(d.booking!==undefined){selectedBooking=Number(d.booking);go('Booking details');return}if(d.address!==undefined){editingAddress=Number(d.address);go('Add address');return}if(d.useAddress!==undefined){const a=addresses[Number(d.useAddress)];address=a.street+(a.landmark?', '+a.landmark:'');fulfil='Delivery';payment='Pay on delivery';go('Bag');return}if(d.defaultAddress!==undefined){const a=addresses[Number(d.defaultAddress)];mutate(async()=>{await api('addresses','POST',{...a,primary:true});await refresh();note('Default address updated.')});return}if(d.removeAddress!==undefined){mutate(async()=>{await api('addresses','DELETE',{id:addresses[Number(d.removeAddress)].id});await refresh();note('Address removed.')});return}if(d.faq!==undefined){activeFaq=activeFaq===Number(d.faq)?null:Number(d.faq);render();app.querySelectorAll('.faq p').forEach(el=>motion(el,[{opacity:.6},{opacity:1}],180));return}if(d.opsOrder!==undefined){const o=opsOrders[Number(d.opsOrder)];mutate(async()=>{await api('operations','PATCH',{type:'order',id:o.id,status:o.status+1});await loadOperations();note('Order status updated.')});return}if(d.opsBooking!==undefined){const o=opsBookings[Number(d.opsBooking)];mutate(async()=>{await api('operations','PATCH',{type:'reservation',id:o.id,status:d.status});await loadOperations();note('Table request updated.')});return}
switch(d.action){case 'open-signin':go('Sign in');break;case 'get-started':go('Sign in');break;case 'demo-signin':enterDemo();break;case 'minus':quantity=Math.max(1,quantity-1);updatePrice();break;case 'plus':quantity=Math.min(20,quantity+1);updatePrice();break;case 'save':{if(!signedIn){gateReturn='Menu';go('Sign in');break}const next=new Set(saved);if(next.has(selected.id))next.delete(selected.id);else next.add(selected.id);mutate(async()=>{await api('account','PATCH',{favourites:[...next]});await refresh();note(next.has(selected.id)?'Saved to your favourites.':'Removed from favourites.')});break}case 'saved':go('Favourites');break;case 'add':{const existing=bag.find(x=>x.meal.id===selected.id&&x.heat===heat&&x.extra===extra);if(existing)existing.qty=Math.min(20,existing.qty+quantity);else bag.push({meal:selected,heat,extra,qty:quantity,unit:selected.price+(extra?1500:0)});orderKey=crypto.randomUUID();go('Bag');note('Added to your bag.');break}case 'order':capture();if(!bag.length)return;if(orderName.trim().length<2||!validPhone(orderPhone)||(fulfil==='Delivery'&&address.trim().length<5)){app.querySelector('#ile-order-error').textContent=orderName.trim().length<2?'Enter your full name.':!validPhone(orderPhone)?'Enter a valid Nigerian phone number.':'Enter your complete delivery address.';return}go('Checkout');break;
case 'place-order':capture();if(!bag.length)return;if(!signedIn){remember();gateReturn='Checkout';go('Sign in');break}mutate(async()=>{const result=await api('orders','POST',orderInput());const id=result.order.id;bag=[];saveBag();orderKey=crypto.randomUUID();orderNotes='';try{sessionStorage.removeItem('ile-resume')}catch{}await refresh(false);selectedOrder=orders.findIndex(o=>o.id===id);booking=result.order;go('Confirmed');note('Demo order saved. No payment was taken.')});break;
case 'new-booking':resetBooking();break;case 'edit-booking':{const b=bookings[selectedBooking];if(!b||b.status==='Cancelled')return;editingBooking=selectedBooking;draft={...b};slot=b.slot;go('Reserve');break}case 'keep-booking':go('Booking details');break;case 'cancel-booking':mutate(async()=>{await api('bookings','PATCH',{id:bookings[selectedBooking].id,cancel:true});await refresh(false);go('Bookings');note('Your table request was cancelled.')});break;case 'new-address':editingAddress=null;go('Add address');break;case 'refresh':refresh().then(()=>note('You’re up to date.')).catch(e=>note(e.message));break;case 'refresh-ops':loadOperations();break}
});
listen('input',e=>{if(e.target.id==='ile-search'){query=e.target.value;app.querySelector('#ile-menu-items').innerHTML=menuItems();icons()}});
listen('change',e=>{const t=e.target;if(t.id==='ile-date'){capture();render();return}if(t.name==='ile-heat')heat=t.value;if(t.id==='ile-extra'){extra=t.checked;updatePrice()}if(t.dataset.pref){const next={...preferences,[t.dataset.pref]:t.checked};mutate(async()=>{await api('account','PATCH',{preferences:next});await refresh();note('Notification preferences updated.')})}});
listen('submit',e=>{const id=e.target.id;if(!['ile-reservation','ile-profile','ile-addressform'].includes(id))return;e.preventDefault();if(busy)return;if(id==='ile-reservation'){capture();if(!availableSlots(draft.date).includes(slot)){render();app.querySelector('#ile-reserve-error').textContent='Choose a future sitting.';return}if(!signedIn){remember();gateReturn='Reserve';go('Sign in');return}mutate(async()=>{const edit=editingBooking!==null;const result=await api('bookings',edit?'PATCH':'POST',{...bookingInput(),...(edit?{id:bookings[editingBooking].id}:{idempotencyKey:bookingKey})});await refresh(false);selectedBooking=bookings.findIndex(b=>b.id===result.booking.id);booking=result.booking;editingBooking=null;bookingKey=crypto.randomUUID();try{sessionStorage.removeItem('ile-resume')}catch{}go('Confirmed');note('Demo table request saved.')});return}if(id==='ile-profile'){const next={name:app.querySelector('#ile-profile-name').value.trim(),phone:app.querySelector('#ile-profile-phone').value.trim(),email:app.querySelector('#ile-profile-email').value.trim()};mutate(async()=>{await api('account','PATCH',{profile:next});await refresh(false);draft.name=profile.name;draft.phone=profile.phone;orderName=profile.name;orderPhone=profile.phone;go('Account');note('Your details are saved.')});return}if(id==='ile-addressform'){const a={label:app.querySelector('#ile-address-label').value,street:app.querySelector('#ile-address-street').value.trim(),landmark:app.querySelector('#ile-landmark').value.trim(),primary:app.querySelector('#ile-address-primary').checked,...(editingAddress!==null?{id:addresses[editingAddress].id}:{})};mutate(async()=>{await api('addresses','POST',a);await refresh(false);if(a.primary)address=a.street+(a.landmark?', '+a.landmark:'');go('Addresses');note('Address saved.')});return}});
function operations(){if(!isStaff)return `${pagehead('Restaurant console','Account')}<section class="section">${blank('clipboard-list','Staff access required','This area is only available to authorised restaurant staff.')}</section>`;return `${pagehead('Restaurant console','Account')}<section class="section">${titleblock('KITCHEN & HOST','The next<br>good gathering.','Manage incoming meals and table requests.')}<button class="secondary cursor-interaction" data-action="refresh-ops">Refresh queue</button><h2 class="queueheading">Orders</h2>${opsOrders.filter(o=>o.status<3).map(o=>{const i=opsOrders.indexOf(o);return `<article class="historycard"><div class="historytop"><span class="mini">${esc(o.reference)}</span><span class="statuspill">${orderSteps(o)[o.status]}</span></div><h2>${esc(o.name)}</h2><p>${esc(o.phone)} · ${o.fulfil}</p><p>${esc(o.address)}</p><div class="orderlines">${o.items.map(b=>`<p><span>${b.qty} × ${b.meal.name} · ${b.heat}${b.extra?' + plantain':''}</span><span>${money(b.unit*b.qty)}</span></p>`).join('')}</div>${o.notes?`<p>${esc(o.notes)}</p>`:''}<div class="summary"><p><span>${o.payment}</span><span>${money(o.total)}</span></p></div><button class="primary wide cursor-interaction" data-ops-order="${i}">${orderSteps(o)[o.status+1]}</button></article>`}).join('')||'<p class="description">No open orders.</p>'}<h2 class="queueheading">Table requests</h2>${opsBookings.filter(b=>b.status!=='Cancelled').map(b=>{const i=opsBookings.indexOf(b);return `<article class="historycard"><div class="historytop"><span class="mini">${esc(b.reference)}</span><span class="statuspill">${b.status}</span></div><h2>${esc(b.name)} · ${b.guests}</h2><p>${dateText(b.date)} · ${b.slot} · ${b.seating}</p><p>${esc(b.phone)} · ${b.occasion}</p>${b.status==='Requested'?`<button class="primary wide cursor-interaction" data-ops-booking="${i}" data-status="Confirmed">Confirm table</button>`:''}<button class="textbutton cursor-interaction" data-ops-booking="${i}" data-status="Cancelled">Cancel request</button></article>`}).join('')||'<p class="description">No table requests.</p>'}</section>`}
async function loadOperations(){try{const data=await api('operations');opsOrders=data.orders;opsBookings=data.bookings;if(view==='Operations')render()}catch(e){note(e.message)}}

const hash=decodeURIComponent(location.hash.slice(1));if(Object.hasOwn(viewFns,hash)&&!['Dish','Confirmed','Cancel booking','Booking details','Add address','Operations'].includes(hash))view=hash;
engagement=mountEngagement({root,meals,onView:go,onDish:id=>{selected=meals.find(m=>m.id===id);if(selected){quantity=1;extra=false;heat='Medium';go('Dish')}}});
render();refresh().catch(e=>note(e.message));
const poll=setInterval(()=>{if(document.visibilityState==='visible'&&!busy&&['Tracking','Orders','Bookings','Booking details'].includes(view))refresh().catch(()=>{})},15000);
const pop=()=>{capture();const v=decodeURIComponent(location.hash.slice(1))||'Welcome';view=Object.hasOwn(viewFns,v)?v:'Home';render()};window.addEventListener('popstate',pop,{signal:controller.signal});
if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
return ()=>{engagement?.stop();controller.abort();clearTimeout(demoEntryTimer);clearInterval(poll)};
}
